#[derive(Deserialize)]
struct QuizParams {
    #[serde(default)]
    title: String,
    /// "Number of winners"; a missing field keeps the current value (or the default).
    winners: Option<String>,
}

/// Validates the quiz form. Returns the number of winners to store, or the errors.
fn validate_quiz(p: &QuizParams, current: i64) -> Result<i64, Vec<String>> {
    let mut errors = vec![];
    if p.title.trim().is_empty() {
        errors.push("Title can't be blank".into());
    }
    let winners = match p.winners.as_deref().map(str::trim) {
        None => Some(current),
        Some(w) => w.parse::<i64>().ok().filter(|n| (1..=10_000).contains(n)),
    };
    if winners.is_none() {
        errors.push("Number of winners must be a whole number, at least 1".into());
    }
    if errors.is_empty() { Ok(winners.unwrap()) } else { Err(errors) }
}

fn winners_input(p: &QuizParams, current: i64) -> String {
    p.winners.clone().unwrap_or_else(|| current.to_string())
}

async fn quiz_create(State(s): State<AppState>, Form(p): Form<QuizParams>) -> AppResult {
    let winners = match validate_quiz(&p, db::DEFAULT_WINNERS) {
        Ok(w) => w,
        Err(errors) => {
            let w = winners_input(&p, db::DEFAULT_WINNERS);
            return Ok(unprocessable(views::quiz_form(None, &p.title, &w, &errors)));
        }
    };
    let id = db::create_quiz(&s.conn(), p.title.trim(), winners)?;
    Ok(see_other(format!("/moderate/quizzes/{id}")))
}

