232:fn random_below(n: usize) -> usize {
233:    let n = n as u64;
234:    let zone = u64::MAX - u64::MAX % n;
235:    loop {
236:        let v = u64::from_le_bytes(random_bytes::<8>());
237:        if v < zone {
238:            return (v % n) as usize;
239:        }
240:    }
241:}
