307:pub async fn screen_events(State(s): State<AppState>, Path(id): Path<i64>, headers: HeaderMap) -> AppResult {
308:    let game = db::get_game(&s.conn(), id)?.ok_or(AppError::NotFound)?;
309:    let hub = s.hub.game(id);
310:    let st = ScreenStream {
311:        url: join_url(&headers, &game.code),
312:        phase_rx: hub.phase.subscribe(),
313:        stats_rx: hub.stats.subscribe(),
314:        shutdown_rx: s.hub.shutdown.subscribe(),
315:        hub,
316:        s: s.clone(),
317:        game_id: id,
318:        last: None,
319:        done: false,
320:    };
321:    let stream = stream::unfold(st, |mut st| async move {
322:        if st.done {
323:            return None;
324:        }
325:        loop {
326:            match st.poll_change() {
327:                Err(()) => {
328:                    st.done = true;
329:                    return Some((Ok(Event::default().event("gone").data("1")), st));
330:                }
331:                Ok(Some(ev)) => return Some((Ok(ev), st)),
332:                Ok(None) => {}
333:            }
334:            let phase_changed = tokio::select! {
335:                biased;
336:                _ = st.shutdown_rx.changed() => return None,
337:                r = st.phase_rx.changed() => if r.is_err() { return None } else { true },
338:                r = st.stats_rx.changed() => if r.is_err() { return None } else { false },
339:            };
340:            // Coalesce bursts of counter changes (many answers at once) into one update. A phase change
341:            // (the moderator moved on) is sent at once, and also cuts a pending coalescing pause short.
342:            if !phase_changed {
343:                tokio::select! {
344:                    biased;
345:                    _ = st.shutdown_rx.changed() => return None,
346:                    r = st.phase_rx.changed() => if r.is_err() { return None },
347:                    _ = tokio::time::sleep(Duration::from_millis(100)) => {}
348:                }
349:            }
350:        }
351:    });
352:    Ok(sse_response(stream))
353:}
