#[derive(Deserialize)]
struct QuizParams {
    #[serde(default)]
    title: String,
    /// "Number of winners"; a missing field keeps the current value (or the default).
    winners: Option<String>,
    /// "Timer minutes" / "Timer seconds"; missing keeps the current value, blank means 0.
    timer_minutes: Option<String>,
    timer_seconds: Option<String>,
}

fn current_settings(quiz: Option<&db::Quiz>) -> db::QuizSettings {
    match quiz {
        Some(q) => db::QuizSettings { winners: q.winners, timer_minutes: q.timer_minutes, timer_seconds: q.timer_seconds },
        None => db::QuizSettings { winners: db::DEFAULT_WINNERS, timer_minutes: 0, timer_seconds: 0 },
    }
}

/// Parses an optional whole number field within `range`; None = invalid. Blank counts as `blank`.
fn number_field(v: Option<&str>, current: i64, blank: Option<i64>, range: std::ops::RangeInclusive<i64>) -> Option<i64> {
    match v.map(str::trim) {
        None => Some(current),
        Some("") => blank,
        Some(w) => w.parse::<i64>().ok().filter(|n| range.contains(n)),
    }
}

/// Validates the quiz form. Returns the settings to store, or the errors.
fn validate_quiz(p: &QuizParams, cur: &db::QuizSettings) -> Result<db::QuizSettings, Vec<String>> {
    let mut errors = vec![];
    if p.title.trim().is_empty() {
        errors.push("Title can't be blank".into());
    }
    let winners = number_field(p.winners.as_deref(), cur.winners, None, 1..=10_000);
    if winners.is_none() {
        errors.push("Number of winners must be a whole number, at least 1".into());
    }
    let minutes = number_field(p.timer_minutes.as_deref(), cur.timer_minutes, Some(0), 0..=999);
    if minutes.is_none() {
        errors.push("Timer minutes must be a whole number from 0 to 999".into());
    }
    let seconds = number_field(p.timer_seconds.as_deref(), cur.timer_seconds, Some(0), 0..=3599);
    if seconds.is_none() {
        errors.push("Timer seconds must be a whole number from 0 to 3599".into());
    }
    if !errors.is_empty() {
        return Err(errors);
    }
    Ok(db::QuizSettings { winners: winners.unwrap(), timer_minutes: minutes.unwrap(), timer_seconds: seconds.unwrap() })
}

/// What the form shows again after a validation error: the submitted text, or the current value.
fn settings_input(p: &QuizParams, cur: &db::QuizSettings) -> views::SettingsInput {
    views::SettingsInput {
        winners: p.winners.clone().unwrap_or_else(|| cur.winners.to_string()),
        timer_minutes: p.timer_minutes.clone().unwrap_or_else(|| cur.timer_minutes.to_string()),
        timer_seconds: p.timer_seconds.clone().unwrap_or_else(|| cur.timer_seconds.to_string()),
    }
}

async fn quiz_create(State(s): State<AppState>, Form(p): Form<QuizParams>) -> AppResult {
    let cur = current_settings(None);
    let settings = match validate_quiz(&p, &cur) {
        Ok(v) => v,
        Err(errors) => {
            return Ok(unprocessable(views::quiz_form(None, &p.title, &settings_input(&p, &cur), &errors)));
        }
    };
    let id = db::create_quiz(&s.conn(), p.title.trim(), &settings)?;
    Ok(see_other(format!("/moderate/quizzes/{id}")))
}

